"use client";

import { useActionState } from "react";
import { signIn } from "@/actions/auth";

export default function LoginPage() {
  const [state, formAction, isPending] = useActionState(signIn, null);

  return (
    <main className="max-w-md mx-auto mt-16 px-4">
      <h1 className="text-3xl font-bold mb-6">
        Login
      </h1>

      <form action={formAction} className="space-y-4">
        <div>
          <input
            name="email"
            type="email"
            placeholder="Email"
            required
            className="border p-3 w-full rounded"
          />
        </div>

        <div>
          <input
            name="password"
            type="password"
            placeholder="Password"
            required
            className="border p-3 w-full rounded"
          />
        </div>

        {state?.error && (
          <p className="text-red-500 text-sm font-medium">{state.error}</p>
        )}

        <button
          type="submit"
          disabled={isPending}
          className="bg-black text-white px-4 py-3 w-full rounded disabled:bg-gray-400 transition-colors"
        >
          {isPending ? "Logging in..." : "Login"}
        </button>
      </form>
    </main>
  );
}

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { signOut } from "@/actions/auth";
import BookmarkForm from "@/components/bookmark-form";
import DeleteBookmarkButton from "@/components/delete-button";
import Link from "next/link";
export default async function DashboardPage() {
  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/login");
  }

  const { data: profile } = await supabase
    .from("profiles")
    .select("handle")
    .eq("id", user.id)
    .single();

    const { data: bookmarks } = await supabase
  .from("bookmarks")
  .select("*")
  .eq("user_id", user.id)
  .order("created_at", { ascending: false });

  return (
    <main className="max-w-5xl mx-auto p-8">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold">
            Dashboard
          </h1>

          <p className="text-gray-600 mt-2">
            {user.email}
          </p>

          <p className="text-sm text-gray-500">
            @{profile?.handle}
          </p>
        </div>

        <form action={signOut}>
          <button
            type="submit"
            className="bg-red-500 text-white px-4 py-2 rounded"
          >
            Logout
          </button>
        </form>
      </div>

      <div className="border rounded-lg p-8">
        <h2 className="text-xl font-semibold mb-4">
          My Bookmarks
        </h2>

        <BookmarkForm />

<div className="space-y-4">
  {bookmarks?.length === 0 ? (
    <p className="text-gray-500">
      No bookmarks yet.
    </p>
  ) : (
    bookmarks?.map((bookmark) => (
      <div
        key={bookmark.id}
        className="border rounded-lg p-4"
      >
        <div className="flex justify-between items-center">
          <h3 className="font-semibold">
            {bookmark.title}
          </h3>

          <span
            className={`text-sm px-2 py-1 rounded ${
              bookmark.is_public
                ? "bg-green-100"
                : "bg-gray-100"
            }`}
          >
            {bookmark.is_public ? "Public" : "Private"}
          </span>
        </div>

        <a
          href={bookmark.url}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-600 break-all"
        >
          {bookmark.url}

        </a>
          <Link
    href={`/dashboard/edit/${bookmark.id}`}
    className="text-blue-600 text-sm"
  >
    Edit
  </Link>

         <DeleteBookmarkButton
      id={bookmark.id}
    />
      </div>

    ))

  )}
</div>
      </div>
    </main>
  );
}

import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

type Props = {
  params: Promise<{
    handle: string;
  }>;
};

export default async function PublicProfilePage({
  params,
}: Props) {
  const { handle } = await params;

  const supabase = await createClient();

  const { data: profile } = await supabase
    .from("profiles")
    .select("id, handle")
    .eq("handle", handle)
    .maybeSingle();

  if (!profile) {
    notFound();
  }

  const { data: bookmarks } = await supabase
    .from("bookmarks")
    .select("*")
    .eq("user_id", profile.id)
    .eq("is_public", true)
    .order("created_at", { ascending: false });

  return (
    <main className="max-w-4xl mx-auto p-8">
      <h1 className="text-3xl font-bold mb-8">
        @{profile.handle}
      </h1>

      <div className="space-y-4">
        {!bookmarks || bookmarks.length === 0 ? (
  <p className="text-gray-500">
    No public bookmarks yet.
  </p>
) : (
  bookmarks.map((bookmark) => (
            <div
              key={bookmark.id}
              className="border rounded-lg p-4"
            >
              <h2 className="font-semibold text-lg">
                {bookmark.title}
              </h2>

              <a
                href={bookmark.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-blue-600 break-all"
              >
                {bookmark.url}
              </a>
            </div>
          ))
        )}
      </div>
    </main>
  );
}

"use client";

import { useActionState } from "react";
import { createBookmark } from "@/actions/bookmarks";

const initialState: {
  error?: string;
  success?: boolean;
} = {};

export default function BookmarkForm() {
  const [state, formAction, pending] =
    useActionState(createBookmark, initialState);

  return (
    <form
      action={formAction}
      className="border rounded-lg p-6 mb-8 space-y-4"
    >
      <h2 className="text-xl font-semibold">
        Add Bookmark
      </h2>

      <input
        name="title"
        placeholder="Bookmark title"
        className="w-full border p-3 rounded"
        required
      />

      <input
        name="url"
        placeholder="https://example.com"
        className="w-full border p-3 rounded"
        required
      />

      <label className="flex items-center gap-2">
        <input type="checkbox" name="isPublic" />
        Public Bookmark
      </label>

      {state?.error && (
        <p className="text-red-500">
          {state.error}
        </p>
      )}

      <button
        type="submit"
        disabled={pending}
        className="bg-black text-white px-4 py-2 rounded"
      >
        {pending ? "Saving..." : "Save Bookmark"}
      </button>
    </form>
  );
}

